        totalBytesSent: 0,
        totalBytesReceived: 0,
        averageJitterInMs: 0,
        averageRoundTripTimeInMs: 0,
        codec: '',
        codecPerTrackType: {},
        timestamp: Date.now(),
        totalConcealedSamples: 0,
        totalConcealmentEvents: 0,
        totalPacketsReceived: 0,
