            return;
        const ring = this.call.state.settings?.ring;
        if (!ring)
            return;
        const isCaller = this.call.isCreatedByMe;
        const timeoutMs = isCaller
            ? ring.auto_cancel_timeout_ms
            : ring.incoming_call_timeout_ms;
