/**
 * Creates a new sound detector.
 *
 * @param audioStream the audio stream to observe. Depending on the provided configuration, this stream might be destroyed when the sound detector is stopped.
 * @param onSoundDetectedStateChanged a callback which is called when the sound state changes.
 * @param options custom options for the sound detector.
 * @returns a clean-up function which once invoked stops the sound detector.
 */
const createSoundDetector = (audioStream, onSoundDetectedStateChanged, options = {}) => {
    const { detectionFrequencyInMs = 500, audioLevelThreshold = 150, fftSize = 128, destroyStreamOnStop = true, } = options;
    const audioContext = new AudioContext();
    const analyser = audioContext.createAnalyser();
    analyser.fftSize = fftSize;
    const microphone = audioContext.createMediaStreamSource(audioStream);
    microphone.connect(analyser);
    const intervalId = setInterval(() => {
        const data = new Uint8Array(analyser.frequencyBinCount);
        analyser.getByteFrequencyData(data);
        const isSoundDetected = data.some((value) => value >= audioLevelThreshold);
        const averagedDataValue = data.reduce((pv, cv) => pv + cv, 0) / data.length;
        const percentage = averagedDataValue > audioLevelThreshold
            ? 100
            : Math.round((averagedDataValue / audioLevelThreshold) * 100);
        // When the track is disabled, it takes time for the buffer to empty
        // This check will ensure that we don't send anything if the track is disabled
        if (audioStream.getAudioTracks()[0]?.enabled) {
            onSoundDetectedStateChanged({ isSoundDetected, audioLevel: percentage });
        }
        else {
            onSoundDetectedStateChanged({ isSoundDetected: false, audioLevel: 0 });
        }
    }, detectionFrequencyInMs);
    return async function stop() {
        clearInterval(intervalId);
        // clean-up the AudioContext elements
        microphone.disconnect();
        analyser.disconnect();
        if (audioContext.state !== 'closed') {
            await audioContext.close();
        }
        // stop the stream
        if (destroyStreamOnStop) {
            audioStream.getTracks().forEach((track) => {
                track.stop();
                audioStream.removeTrack(track);
            });
        }
    };
};

/**
 * Analyzes time-domain waveform data to determine if audio is being captured.
 * Uses the waveform RMS around the 128 midpoint for robust silence detection.
 */
const hasAudio = (analyser) => {
    const data = new Uint8Array(analyser.fftSize);
    analyser.getByteTimeDomainData(data);
    let squareSum = 0;
    for (const sample of data) {
        const centered = sample - 128;
        // Ignore tiny quantization/jitter around midpoint (e.g. 127/128 samples).
        const signal = Math.abs(centered) <= 1 ? 0 : centered;
        squareSum += signal * signal;
    }
    const rms = Math.sqrt(squareSum / data.length);
    return rms > 0;
};
/** Helper for "no event" transitions */
const noEmit = (nextState) => ({
    shouldEmit: false,
    nextState,
});
/** Helper for event-emitting transitions */
const emit = (capturesAudio, nextState) => ({ shouldEmit: true, nextState, capturesAudio });
/**
 * State transition function - computes next state and whether to emit an event.
 */
const transitionState = (state, audioDetected, options) => {
    if (audioDetected) {
        // Any observed audio means the microphone is capturing.
        // Emit recovery/success and let the caller stop the detector.
        return emit(true, { kind: 'IDLE' });
    }
    const { noAudioThresholdMs, emitIntervalMs } = options;
    const now = Date.now();
    switch (state.kind) {
        case 'IDLE':
            return noEmit({ kind: 'DETECTING', noAudioStartTime: now });
        case 'DETECTING': {
            const { noAudioStartTime } = state;
            const elapsed = now - noAudioStartTime;
            return elapsed >= noAudioThresholdMs
                ? emit(false, { kind: 'EMITTING', noAudioStartTime, lastEmitTime: now })
                : noEmit(state);
        }
        case 'EMITTING': {
            const timeSinceLastEmit = now - state.lastEmitTime;
            return timeSinceLastEmit >= emitIntervalMs
                ? emit(false, { ...state, lastEmitTime: now })
                : noEmit(state);
        }
    }
};
/**
 * Creates and configures an audio analyzer for the given stream.
 */
const createAudioAnalyzer = (audioStream, fftSize) => {
    const audioContext = new AudioContext();
    const analyser = audioContext.createAnalyser();
    analyser.fftSize = fftSize;
    const microphone = audioContext.createMediaStreamSource(audioStream);
    microphone.connect(analyser);
    return { audioContext, analyser };
};
/**
 * Creates a new no-audio detector that monitors continuous absence of audio on an audio stream.
 *
 * @param audioStream the audio stream to observe.
 * @param options custom options for the no-audio detector.
 * @returns a cleanup function which once invoked stops the no-audio detector.
 */
const createNoAudioDetector = (audioStream, options) => {
    const { detectionFrequencyInMs = 350, fftSize = 512, onCaptureStatusChange, } = options;
    let state = { kind: 'IDLE' };
    const { audioContext, analyser } = createAudioAnalyzer(audioStream, fftSize);
    const detectionIntervalId = setInterval(() => {
        const [track] = audioStream.getAudioTracks();
        if (track && !track.enabled) {
            state = { kind: 'IDLE' };
            return;
        }
        // Missing or ended track is treated as no-audio to surface abrupt capture loss.
        const audioDetected = track?.readyState === 'live' && hasAudio(analyser);
        const transition = transitionState(state, audioDetected, options);
        state = transition.nextState;
        if (!transition.shouldEmit)
            return;
        const { capturesAudio } = transition;
        onCaptureStatusChange(capturesAudio);
        if (capturesAudio) {
            stop().catch((err) => {
                const logger = videoLoggerSystem.getLogger('NoAudioDetector');
                logger.error('Error stopping no-audio detector', err);
            });
        }
    }, detectionFrequencyInMs);
    async function stop() {
        clearInterval(detectionIntervalId);
        if (audioContext.state !== 'closed') {
            await audioContext.close();
        }
    }
    return stop;
};

