    /**
     * Handles the reconnection flow.
     *
     * @internal
     *
     * @param strategy the reconnection strategy to use.
     * @param reason the reason for the reconnection. Pass a `ReconnectReason.*`
     *   constant when the SDK should react to it (e.g.
     *   `ICE_NEVER_CONNECTED` increments the unsupported-network counter).
     */
    reconnect = async (strategy, reason) => {
        const { callingState } = this.state;
        if (callingState === CallingState.JOINING ||
            callingState === CallingState.RECONNECTING ||
            callingState === CallingState.MIGRATING ||
            callingState === CallingState.LEFT ||
            callingState === CallingState.RECONNECTING_FAILED)
            return;
        // Drop redundant reconnect calls. If a reconnect is already queued or
        // running for this Call, that entry will resolve whatever broke;
        // queueing more entries just replays the full REJOIN cycle (one extra
        // `POST /join` per entry) once the call is already healthy again.
        if (hasPending(this.reconnectConcurrencyTag))
            return;
        const reconnectLeaveGeneration = this.leaveGeneration;
        const supersededByLeave = () => this.leaveGeneration !== reconnectLeaveGeneration;
        return withoutConcurrency(this.reconnectConcurrencyTag, async () => {
            if (supersededByLeave())
                return;
            const reconnectStartTime = Date.now();
            this.reconnectStrategy = strategy;
            this.reconnectReason = reason;
            const sfuRejoinFailures = new Map();
            const markAsReconnectingFailed = async () => {
                if (supersededByLeave())
                    return;
                try {
                    // attempt to fetch the call data from the server, as the call
                    // state might have changed while we were reconnecting or were offline
                    await this.get();
                }
                finally {
                    if (!supersededByLeave()) {
                        this.state.setCallingState(CallingState.RECONNECTING_FAILED);
                    }
                }
            };
            const giveUpAndLeave = async (message) => {
                this.logger.warn(`[Reconnect] Giving up: ${message}. Leaving the call.`);
                // If we're mid-iteration, the state can be JOINING; `Call.leave` would
                // then wait for JOINED before proceeding, but no more attempts will run
                // so JOINED never comes. Transition to RECONNECTING so `leave()` proceeds.
                if (this.state.callingState === CallingState.JOINING) {
                    this.state.setCallingState(CallingState.RECONNECTING);
                }
                try {
                    await this.leave({ message });
                }
                catch (err) {
                    this.logger.warn(`[Reconnect] leave() failed after ${message}`, err);
                }
            };
            // Count this entry into reconnect if it was triggered by a peer
            // connection that never reached `connected`/`completed`.
            if (reason === ReconnectReason.ICE_NEVER_CONNECTED) {
                this.iceFailuresWithoutConnect++;
                if (this.iceFailuresWithoutConnect >= this.maxIceFailuresWithoutConnect) {
                    await giveUpAndLeave('webrtc_unsupported_network');
                    return;
                }
            }
            let attempt = 0;
            do {
                const reconnectingTime = Date.now() - reconnectStartTime;
                const shouldGiveUpReconnecting = this.disconnectionTimeoutSeconds > 0 &&
                    reconnectingTime / 1000 > this.disconnectionTimeoutSeconds;
                if (shouldGiveUpReconnecting) {
                    this.logger.warn('[Reconnect] Stopping reconnection attempts after reaching disconnection timeout');
                    await markAsReconnectingFailed();
                    return;
                }
                // Rejoin rate limit: bound the number of REJOIN (and MIGRATE)
                // transitions inside a rolling window. FAST is not counted because
                // it does not issue a new backend `joinCall`.
                if (this.reconnectStrategy === WebsocketReconnectStrategy.REJOIN ||
                    this.reconnectStrategy === WebsocketReconnectStrategy.MIGRATE) {
                    if (!this.rejoinRateLimiter.tryRegister()) {
                        await giveUpAndLeave('rejoin_attempt_limit_exceeded');
                        return;
                    }
                }
                // we don't increment reconnect attempts for the FAST strategy.
                if (this.reconnectStrategy !== WebsocketReconnectStrategy.FAST) {
                    this.reconnectAttempts++;
                }
                const attemptedStrategy = this.reconnectStrategy;
                const currentStrategy = WebsocketReconnectStrategy[attemptedStrategy];
                try {
                    // wait until the network is available
                    await this.networkAvailableTask?.promise;
                    if (supersededByLeave())
                        return;
                    this.logger.info(`[Reconnect] Reconnecting with strategy ${WebsocketReconnectStrategy[this.reconnectStrategy]}`);
                    switch (this.reconnectStrategy) {
                        case WebsocketReconnectStrategy.UNSPECIFIED:
                        case WebsocketReconnectStrategy.DISCONNECT:
                            this.logger.debug(`[Reconnect] No-op strategy ${currentStrategy}`);
                            break;
                        case WebsocketReconnectStrategy.FAST:
                            await this.reconnectFast();
                            break;
                        case WebsocketReconnectStrategy.REJOIN: {
                            const confirmedBadSfus = Array.from(sfuRejoinFailures)
                                .filter(([, failures]) => failures >= 2)
                                .map(([sfu]) => sfu);
                            if (this.joinCallData && confirmedBadSfus.length) {
                                this.joinCallData.migrating_from =
                                    confirmedBadSfus[confirmedBadSfus.length - 1];
                                this.joinCallData.migrating_from_list = confirmedBadSfus;
                            }
                            try {
                                await this.reconnectRejoin();
                            }
                            finally {
                                delete this.joinCallData?.migrating_from;
                                delete this.joinCallData?.migrating_from_list;
                            }
                            break;
                        }
                        case WebsocketReconnectStrategy.MIGRATE:
                            await this.reconnectMigrate();
                            break;
                        default:
                            ensureExhausted(this.reconnectStrategy, 'Unknown reconnection strategy');
                            break;
                    }
                    // reconnection worked — reset the negotiation-failure streak.
                    this.consecutiveNegotiationFailures = 0;
                    break; // do-while loop, reconnection worked, exit the loop
                }
                catch (error) {
                    if (supersededByLeave())
                        return;
                    if (attemptedStrategy === WebsocketReconnectStrategy.REJOIN) {
                        const failedSfu = this.credentials?.server.edge_name;
                        if (failedSfu) {
                            const switchSfu = error instanceof SfuJoinError &&
                                SfuJoinError.isJoinErrorCode(error.errorEvent);
                            const failures = (sfuRejoinFailures.get(failedSfu) ?? 0) + 1;
                            sfuRejoinFailures.set(failedSfu, switchSfu ? Math.max(failures, 2) : failures);
                        }
                    }
                    if (this.state.callingState === CallingState.OFFLINE) {
                        this.logger.debug(`[Reconnect] Can't reconnect while offline, stopping reconnection attempts`);
                        break;
                        // we don't need to handle the error if the call is offline
                        // network change event will trigger the reconnection
                    }
                    if (error instanceof ErrorFromResponse && error.unrecoverable) {
                        this.logger.warn(`[Reconnect] Can't reconnect due to coordinator unrecoverable error`, error);
                        await markAsReconnectingFailed();
                        return;
                    }
                    if (error instanceof NegotiationError) {
                        this.consecutiveNegotiationFailures++;
                        if (this.consecutiveNegotiationFailures >=
                            this.maxConsecutiveNegotiationFailures) {
                            await giveUpAndLeave('repeated_negotiation_failures');
                            return;
                        }
                    }
                    // exponential backoff with jitter, capped at 5 s
                    await sleep(retryInterval(attempt));
                    if (supersededByLeave())
                        return;
                    const wasMigrating = this.reconnectStrategy === WebsocketReconnectStrategy.MIGRATE;
                    const mustPerformRejoin = (Date.now() - reconnectStartTime) / 1000 >
                        this.fastReconnectDeadlineSeconds;
                    // don't immediately switch to the REJOIN strategy, but instead attempt
                    // to reconnect with the FAST strategy for a few times before switching.
                    // in some cases, we immediately switch to the REJOIN strategy.
                    const shouldRejoin = mustPerformRejoin || // if we are past the fast reconnect deadline
                        wasMigrating || // if we were migrating, but the migration failed
                        attempt >= 3 || // after 3 failed attempts
                        !(this.publisher?.isHealthy() ?? true) || // if the publisher is not healthy
                        !(this.subscriber?.isHealthy() ?? true); // if the subscriber is not healthy
                    attempt++;
                    const nextStrategy = shouldRejoin
                        ? WebsocketReconnectStrategy.REJOIN
                        : WebsocketReconnectStrategy.FAST;
                    this.reconnectStrategy = nextStrategy;
                    this.logger.info(`[Reconnect] ${currentStrategy} (${this.reconnectAttempts}) failed. Attempting with ${WebsocketReconnectStrategy[nextStrategy]}`, error);
                }
            } while (!supersededByLeave() &&
                this.state.callingState !== CallingState.JOINED &&
                this.state.callingState !== CallingState.RECONNECTING_FAILED &&
                this.state.callingState !== CallingState.LEFT);
            this.logger.info('[Reconnect] Reconnection flow finished');
        });
    };
